import{_ as l,a0 as r,w as o,s as d,ao as p,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const J=JSON.parse('{"title":"面向 Java 開發人員的 JVM 參數指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向 Java 開發人員的 JVM 參數指南 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向 Java 開發人員的 JVM 參數指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向 Java 開發人員的 JVM 參數指南 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220414 A guide to JVM parameters for Java developers","title":"面向 Java 開發人員的 JVM 參數指南","tag":"202205","desc":""},"relativePath":"202205/20220414 A guide to JVM parameters for Java developers.md","filePath":"[post].md"}'),h={name:"202205/20220414 A guide to JVM parameters for Java developers.md"};function c(u,a,g,v,b,k){const e=r("Link");return o(),d("div",null,[a[25]||(a[25]=p(`<h1 id="面向-java-開發人員的-jvm-參數指南" tabindex="-1">面向 Java 開發人員的 JVM 參數指南 <a class="header-anchor" href="#面向-java-開發人員的-jvm-參數指南" aria-label="Permalink to “面向 Java 開發人員的 JVM 參數指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/06/134624iiubdjkqmxaaqhmx.jpg" alt=""></p><blockquote><p>通過理解和使用 JVM 以及 JVM 參數，開發人員和最終用户都可以診斷故障並且提高 Java 應用程序的性能。</p></blockquote><p>當你在編寫源代碼時，你是在編寫人類可以閲讀的代碼。在將代碼編譯成機器語言之前，計算機無法執行它。機器語言是一個通用術語，指的是特定機器所需的任意數量的語言。通常，如果你在 Linux 上編譯代碼，它只能 Linux 上運行；如果你在 Windows 上編譯代碼，它就只在 Windows 上運行。但是，Java 是不同的，它並不以真實的機器為目標，而是面向 <ruby>Java 虛擬機<rt>Java Virtual Machine</rt></ruby>（JVM）。因此，它可以在任何機器上運行。</p><p>Java 源代碼被編譯成<ruby>字節碼<rt>bytecode</rt></ruby>，然後由安裝在計算機上的 JVM 運行。JVM 是一個執行引擎，但我們通常不會直接與它交互。它在後台靜默運行，替我們處理 Java 字節碼。大多數人不需要考慮，甚至也不需要知道 JVM。但是，瞭解它的工作原理是對我們來説是非常有用的，因為這會有助於我們調試和優化 Java 代碼。例如：</p><ul><li>在生產環境中，你發現已經部署的應用程序可能需要提升性能。</li><li>如果你寫的應用程序出錯了，開發人員和最終用户都可以選擇對問題進行調試。</li><li>如果你想了解關於 JDK（即 <ruby>Java 開發工具包<rt>Java Development Kit</rt></ruby>，用於開發/運行 Java 應用程序）的詳細信息，你可以通過查詢 JVM 來獲取。</li></ul><p>本文介紹了一些基礎的 JVM 參數，希望在這些場景中可以提供幫助。</p><p><img src="https://opensource.com/sites/default/files/2022-03/java-jvm-parameters.jpg" alt="JVM 參數"></p><p>（圖源：Jayashree Huttanagoudar，CC BY-SA 4.0）</p><h3 id="jvm、jdk-和-jre-有什麼不同" tabindex="-1">JVM、JDK 和 JRE 有什麼不同？ <a class="header-anchor" href="#jvm、jdk-和-jre-有什麼不同" aria-label="Permalink to “JVM、JDK 和 JRE 有什麼不同？”">​</a></h3><p>Java 有許多 J 開頭的縮略詞，包括 JVM、JDK 和 JRE。</p><ul><li><ruby>Java 開發工具包<rt>Java Development Kit</rt></ruby>（JDK）可供需要在代碼中使用開發庫的程序員使用。</li><li><ruby>Java 運行時環境<rt>Java Runtime Environment</rt></ruby>（JRE）可供想運行 Java 應用程序的人使用。</li><li><ruby>Java 虛擬機<rt>Java Virtual Machine</rt></ruby>（JVM）是運行 Java 字節碼的組件。</li></ul><p>JDK 同時包含 JRE 和 JVM，但有些 Java 發行版提供了包含 JRE（包括 JVM）的替代下載。</p><p><img src="https://opensource.com/sites/default/files/2022-03/jdk.jpg" alt="JDK"></p><p>（圖源：Jayashree Huttanagoudar，CC BY-SA 4.0）</p><p>Java 是開源的，因此，許多不同的公司都會構建和發行他們自己的 JDK 發行版。你可以在系統上安裝多個 JDK，這會對你參與或者運行不同的 Java 項目時很有幫助，因為其中一些項目可能使用舊版本的 JDK。</p><p>你可以使用 <code>alternatives</code> 命令，來查看 Linux 系統上的 JDK 列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alternatives --config java</span></span>
<span class="line"><span>There are 2 programs that provide java.</span></span>
<span class="line"><span>Selection Command</span></span>
<span class="line"><span>-----------------------------------------------</span></span>
<span class="line"><span>*+ 1 java-11-openjdk.x86_64 (/usr/lib/jvm/java-11-openjdk-11.0.13.0.8-2.fc35.x86_64/bin/java)</span></span>
<span class="line"><span>2 java-1.8.0-openjdk.x86_64 (/usr/lib/jvm/java-1.8.0-openjdk-1.8.0.312.b07-2.fc35.x86_64/jre/bin/java)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter to keep the current selection[+], or type selection number:</span></span></code></pre></div><p>如果想要在可用的 JDK 之間進行切換，請再次執行該命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo alternatives --config java</span></span></code></pre></div>`,20)),n("p",null,[a[1]||(a[1]=s("或者可以使用 ",-1)),i(e,{href:"https://opensource.com/%5Bhttps%3A//opensource.com/article/22/3/manage-java-versions-sdkman%5D%28https%3A//opensource.com/article/22/3/manage-java-versions-sdkman%29"},{default:t(()=>[...a[0]||(a[0]=[s("SDKMan",-1)])]),_:1}),a[2]||(a[2]=s("，它可以下載、更新和管理系統中的所有 JDK。",-1))]),a[26]||(a[26]=p(`<h3 id="什麼是-jvm-調優" tabindex="-1">什麼是 JVM 調優？ <a class="header-anchor" href="#什麼是-jvm-調優" aria-label="Permalink to “什麼是 JVM 調優？”">​</a></h3><p>JVM 調優指的是，通過調整 JVM 參數，來提高 Java 應用程序性能的過程，它還有助於診斷應用程序的故障。</p><p>通常情況下，在調試之前需要考慮以下幾點：</p><ul><li><strong>成本</strong>：有時改進運行代碼的硬件可以提高應用程序的性能。這可能看起來像是在“作弊”，但請考慮你願意花多少時間調整 JVM 參數。有時應用程序需要更多的內存來執行所需的功能，而這點是任何軟件技術都無法改變的。</li><li><strong>期望結果</strong>：長期來看，穩定性比性能更重要。如果你的調優對穩定性產生了影響，那麼謹慎地選擇你的調優參數可能會更好。</li><li><strong>底層問題</strong>：有時，問題可能是主機操作系統的底層問題。那麼，在調整 JVM 之前，請確保 JVM 平台按預期工作。</li><li><strong>內存泄漏</strong>：如果你在使用垃圾回收（GC）調優參數，那麼，應用程序代碼中很可能會存在需要修復的內存泄漏。</li></ul><h3 id="參數類型" tabindex="-1">參數類型 <a class="header-anchor" href="#參數類型" aria-label="Permalink to “參數類型”">​</a></h3><p>JVM 參數可以分為以下三類：標準參數、非標準參數和高級選項。</p><h4 id="標準參數" tabindex="-1">標準參數 <a class="header-anchor" href="#標準參數" aria-label="Permalink to “標準參數”">​</a></h4><p>所有的 JVM 實現都支持標準參數，在終端執行 <code>java</code> 命令來查看標準參數列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java</span></span>
<span class="line"><span>Usage: java [options] &lt;mainclass&gt; [args...]</span></span>
<span class="line"><span>        (to execute a class)</span></span>
<span class="line"><span>   or  java [options] -jar &lt;jarfile&gt; [args...]</span></span>
<span class="line"><span>        (to execute a jar file)</span></span>
<span class="line"><span></span></span>
<span class="line"><span> where options include:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        -cp &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>        -classpath &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>        --class-path &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>                A : separated list of directories, JAR archives,</span></span>
<span class="line"><span>                and ZIP archives to search for class files.</span></span>
<span class="line"><span>        --enable-preview</span></span>
<span class="line"><span>                allow classes to depend on preview features of this release</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To specify an argument for a long option, you can use --&lt;name&gt;=&lt;value&gt; or</span></span>
<span class="line"><span>--&lt;name&gt; &lt;value&gt;.</span></span></code></pre></div>`,9)),n("p",null,[a[4]||(a[4]=s("這些是所有 JVM 都會包含的標準參數，你可以像使用任何 ",-1)),i(e,{href:"https://opensource.com/%5Bhttps%3A//opensource.com/article/21/8/linux-terminal%5D%28https%3A//opensource.com/article/21/8/linux-terminal%29"},{default:t(()=>[...a[3]||(a[3]=[s("命令列選項",-1)])]),_:1}),a[5]||(a[5]=s(" 一樣安全地使用它們。例如，要驗證配置的命令選項，創建 VM 並加載主類而不執行主類，請使用：",-1))]),a[27]||(a[27]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java --dry-run &lt;classfile&gt;</span></span></code></pre></div><h4 id="非標準參數" tabindex="-1">非標準參數 <a class="header-anchor" href="#非標準參數" aria-label="Permalink to “非標準參數”">​</a></h4><p>非標準選項以 <code>-X</code> 開頭。這些是通用的，並且特定於 JVM 的特定實現。要列出這些參數，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -X</span></span>
<span class="line"><span>-Xbatch disable background compilation</span></span>
<span class="line"><span>-Xbootclasspath/a:&lt;directories and zip/jar files separated by :&gt;</span></span>
<span class="line"><span>append to end of bootstrap class path</span></span>
<span class="line"><span>-Xinternalversion</span></span>
<span class="line"><span>displays more detailed JVM version information than the</span></span>
<span class="line"><span>-version option</span></span>
<span class="line"><span>-Xloggc:&lt;file&gt; log GC status to a file with time stamps</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在這些參數可能會不經通知就發生變化。而且，並非所有 JVM 實現都支持這些參數。</p><p>微軟構建的 JVM 可能與 RedHat 構建的 JVM 有不同的參數，諸如此類。</p><p>要獲取詳細的 JVM 版本信息，請使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -Xinternalversion --version</span></span>
<span class="line"><span>OpenJDK 64-Bit Server VM (11.0.13+8) for linux-amd64 JRE (11.0.13+8), built on Nov 8 2021 00:00:00 by &quot;mockbuild&quot; with gcc 11.2.1 20210728 (Red Hat 11.2.1-1)</span></span></code></pre></div><p>要獲取這些屬性設置，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XshowSettings:properties --version</span></span></code></pre></div><h4 id="高級選項" tabindex="-1">高級選項 <a class="header-anchor" href="#高級選項" aria-label="Permalink to “高級選項”">​</a></h4><p>這些參數不是隨意使用的，而是用於調整 Hotspot VM 的特定區域。這些參數可能會發生變化，並且不能保證得到所有 JVM 實現的支持。</p><p>這些參數以 <code>-XX</code> 開頭。如需列出參數列表，使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XX:+UnlockDiagnosticVMOptions -XX:+PrintFlagsFinal -version</span></span></code></pre></div><p>例如，需要跟蹤類的加載，那麼使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XX:+TraceClassLoading Hello</span></span></code></pre></div><p>在 <code>Hello.java</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Hello {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    System.out.println(&quot;Inside Hello World!&quot;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>另一個可能會面臨的問題是 OOM（<ruby>內存超出<rt>Out Of Memory</rt></ruby>）錯誤，它發生的時候可能沒有太多的調試信息。為了解決這個問題，使用調試參數 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，它可以創建一個帶有調試信息的 <code>.hprof</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// TestClass.java</span></span>
<span class="line"><span>import java.util.ArrayList;</span></span>
<span class="line"><span>import java.util.List;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class TestClass {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    List&lt;Object&gt; list = new ArrayList&lt;Object&gt;();</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 1000; i++) {</span></span>
<span class="line"><span>      list.add(new char[1000000]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Javac TestClass.java</span></span>
<span class="line"><span>$ java -XX:+HeapDumpOnOutOfMemoryError -Xms10m -Xmx1g TestClass</span></span>
<span class="line"><span>java.lang.OutOfMemoryError: java heap space</span></span>
<span class="line"><span>Dumping heap to java_pid444496.hprof ...</span></span>
<span class="line"><span>Heap dump file created [1018925828 bytes in 1.442 secs]</span></span>
<span class="line"><span>Exception in thread &quot;main&quot; java.lang.OutOfMemoryError: java heap space</span></span>
<span class="line"><span>at TestClass.main(TestClass.Java:8)</span></span></code></pre></div>`,21)),n("p",null,[i(e,{href:"https://opensource.com/%5Bhttps%3A//docs.oracle.com/javase/7/docs/technotes/tools/share/jhat.html%5D%28https%3A//docs.oracle.com/javase/7/docs/technotes/tools/share/jhat.html%29"},{default:t(()=>[...a[6]||(a[6]=[s("有一些工具",-1)])]),_:1}),a[7]||(a[7]=s(" 可以查看這個 ",-1)),a[8]||(a[8]=n("code",null,".hprof",-1)),a[9]||(a[9]=s(" 文件以瞭解問題所在。",-1))]),a[28]||(a[28]=n("h3",{id:"總結",tabindex:"-1"},[s("總結 "),n("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),a[29]||(a[29]=n("p",null,"通過了解和使用 JVM 以及 JVM 參數，開發人員和終端用户都可以診斷故障並提高 Java 應用程序的性能。下次使用 Java 時，請花點時間看看有哪些參數可以用吧！",-1)),a[30]||(a[30]=n("hr",null,null,-1)),n("p",null,[a[11]||(a[11]=s("via: ",-1)),i(e,{href:"https://opensource.com/article/22/4/jvm-parameters-java-developers"},{default:t(()=>[...a[10]||(a[10]=[s("https://opensource.com/article/22/4/jvm-parameters-java-developers",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=s("作者：",-1)),i(e,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:t(()=>[...a[12]||(a[12]=[s("Jayashree Huttanagoudar",-1)])]),_:1}),a[17]||(a[17]=s(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:t(()=>[...a[13]||(a[13]=[s("lkxed",-1)])]),_:1}),a[18]||(a[18]=s(" 譯者：",-1)),i(e,{href:"https://github.com/Veryzzj"},{default:t(()=>[...a[14]||(a[14]=[s("Veryzzj",-1)])]),_:1}),a[19]||(a[19]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[22]||(a[22]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[s("Linux中國",-1)])]),_:1}),a[24]||(a[24]=s(" 榮譽推出",-1))])])}const j=l(h,[["render",c]]);export{J as __pageData,j as default};
